import type { ResponseError } from '@ilpachi/use-alova'
import { getPachiI18n, pachiT } from '@ilpachi/pachi-i18n'
import { getPachiQuasar } from './quasar-instance'

export interface ErrorResponse {
  detail: Detail[] | string
}

export interface Detail {
  type: string
  loc: string[]
  msg: string
  input: string
  /** Stable error code generated by the backend (e.g. `auth.invalid_credentials`); absent for FastAPI 422/404/405. */
  code?: string
  /** Variable parts of the message (e.g. `{ min_length: 12 }`), present only when needed. */
  params?: Record<string, string | number>
}

/**
 * Escapes the special HTML characters of a text coming from the server.
 *
 * @param text - text to make safe
 * @returns text with HTML entities
 */
export function escapeHtml(text: string): string {
  return text.replace(
    /[&<>"']/g,
    c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[c] ?? c
  )
}

/**
 * Shows an error notification (toast).
 *
 * @param _err - original HTTP error
 * @param title - notification title
 * @param html - detail (plain text: it is escaped)
 */
export const toastMessage = (_err: ResponseError, title: string, html: string) => {
  // the text comes from the server: escape here (the notification interprets HTML)
  getPachiQuasar().notify({
    type: 'negative',
    message: escapeHtml(title),
    caption: escapeHtml(html),
    html: true,
    timeout: 5000,
    position: 'top-right'
  })
  return Promise.resolve()
}

/**
 * Shows a modal error dialog and waits for it to be closed.
 *
 * @param _err - original HTTP error
 * @param title - dialog title
 * @param html - dialog HTML content
 */
export const boxMessage = (_err: ResponseError, title: string, html: string) => {
  return new Promise<void>(resolve => {
    getPachiQuasar().dialog({
      title,
      message: html,
      html: true,
      ok: { label: pachiT('common.ok'), flat: true },
      persistent: false
    })
      .onOk(() => resolve())
      .onCancel(() => resolve())
      .onDismiss(() => resolve())
  })
}

/**
 * Text to show for a backend error: translation of `errors.codes.<code>` in the current language
 * (with `params` for the placeholders); if the translation is missing or the error has no `code` it falls back to `msg`.
 *
 * @param item - error detail
 */
export function translateDetail(item: Detail): string {
  const key = item.code ? `errors.codes.${item.code}` : ''
  // `te` with a dynamic key: avoids the recursive typing of the messages schema
  const global = getPachiI18n()?.global as unknown as { te: (key: string) => boolean } | undefined
  if (key && global?.te(key)) return pachiT(key, { ...item.params })
  return item.msg
}

/**
 * Converts the validation details (FastAPI format) into a Quasar-style HTML list.
 *
 * @param items - per-field error details
 * @returns HTML markup of the list
 */
function asQList(items: Detail[]) {
  const litems: string[] = ['<div class="q-list q-list--bordered q-list--separator" role="list">']
  items.forEach(item => {
    litems.push(`<div class="q-item q-item-type row no-wrap q-list--dense" role="listitem">
    <div class="q-item__section column q-item__section--main justify-center">
      ${item.loc?.length ? `<div class="q-item__label">${escapeHtml(item.loc.join('.'))}</div>` : ''}
      <div class="q-item__label q-item__label--caption text-caption">${escapeHtml(translateDetail(item))}</div>
    </div>
  </div>`)
  })
  litems.push('</div>')
  return litems.join('')
}

/**
 * Converts the `detail` of an error response into safe HTML: list for validation errors,
 * text for strings; for a missing `detail` or an object (e.g. 5xx) it uses a translated generic message.
 *
 * @param detail - `detail` field of the response (any type)
 * @returns HTML to show in the dialog
 */
export function formatDetail(detail: unknown): string {
  if (Array.isArray(detail) && detail.length > 0) return asQList(detail as Detail[])
  if (typeof detail === 'string' && detail.trim()) return escapeHtml(detail)
  return escapeHtml(pachiT('errors.http.generic'))
}

/**
 * Shows the user the message of an HTTP error (dialog with status title + detail).
 *
 * @param err - HTTP error returned by the client
 */
export async function errorMessage(err: ResponseError) {
  // JSON body ({ detail }), plain text or absent (network error: the error message is used)
  const body: unknown = await err.safeResponseData()
  const detail = body !== null && typeof body === 'object' ? (body as { detail?: unknown }).detail : (body ?? err.message)
  // 429 without a usable detail: dedicated message (request/attempt limit)
  const hasDetail = Array.isArray(detail) ? detail.length > 0 : typeof detail === 'string' && !!detail.trim()
  const messages =
    err.status === 429 && !hasDetail
      ? escapeHtml(pachiT('errors.http.tooManyRequests'))
      : formatDetail(detail)
  const title = pachiT('errors.http.title', { status: err.status, statusText: err.statusText })
  await boxMessage(err, title, messages)
}
